'use strict';
// Build the one-file deployment form of the DCS compatibility probe.
// Sources stay modular; the generated file wraps each module in a local
// function and returns a small entry table (install_export / run_hook).
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
const { findLua } = require('./build_common.cjs');

const ROOT = path.resolve(__dirname, '..');
const OUTPUT = path.join(ROOT, 'dist', 'dev', 'aesa_compat_probe.lua');

const MODULES = [
  ['ExportApi', 'src/adapters/dcs/api/export.lua'],
  ['HookApi', 'src/adapters/dcs/api/hook.lua'],
  ['NativeApi', 'src/adapters/dcs/api/native.lua'],
  ['ProfileModule', 'src/adapters/dcs/compat/profile.lua'],
  ['ProbeModule', 'src/adapters/dcs/compat/probe.lua'],
  ['ProfileData', 'src/adapters/dcs/compat/profiles/dcs-2.9.30.28738-mt.lua'],
  ['EntryModule', 'src/adapters/dcs/compat/entry_bundle.lua'],
];

function sha256(text) {
  return crypto.createHash('sha256').update(text).digest('hex');
}

function moduleSource(name, relative) {
  const source = fs.readFileSync(path.join(ROOT, relative), 'utf8');
  return `-- ---- ${relative} ----\nlocal function __${name}()\n${source}\nend\nlocal ${name} = __${name}()\n`;
}

function build() {
  const pieces = MODULES.map(([name, relative]) => moduleSource(name, relative));
  const hashes = Object.fromEntries(MODULES.map(([, relative]) => [
    relative,
    sha256(fs.readFileSync(path.join(ROOT, relative))),
  ]));
  const header = [
    '-- DO NOT EDIT -- generated by scripts/build_compat_probe.cjs',
    '-- One-file DCS compatibility probe (export + hook entry).',
    `-- source-sha256: ${sha256(JSON.stringify(hashes))}`,
    '-- inputs:',
    ...Object.entries(hashes).map(([file, hash]) => `--   ${file} ${hash}`),
    '',
  ].join('\n');
  const footer = [
    '',
    'return EntryModule({',
    '    export = ExportApi,',
    '    hook = HookApi,',
    '    native = NativeApi,',
    '    profile = ProfileModule,',
    '    probe = ProbeModule,',
    '    profile_data = ProfileData,',
    '})',
    '',
  ].join('\n');
  return header + pieces.join('\n') + footer;
}

function checkLua(text) {
  const lua = findLua();
  if (!lua) return { checked: false, reason: 'luae.exe not found' };
  const temp = path.join(os.tmpdir(), `aesa-compat-probe-${process.pid}.lua`);
  fs.writeFileSync(temp, text);
  let result;
  try {
    result = spawnSync(lua, ['-e', `assert(loadfile(${JSON.stringify(temp)}))`], {
      encoding: 'utf8',
      timeout: 30000,
      windowsHide: true,
    });
  } finally {
    fs.rmSync(temp, { force: true });
  }
  if (result.error || result.status !== 0) {
    const why = result.error ? result.error.message : `${result.stdout || ''}${result.stderr || ''}`;
    return { checked: true, ok: false, reason: why.trim() };
  }
  return { checked: true, ok: true };
}

function write() {
  const text = build();
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, text);
  return { text, output: OUTPUT, lua: checkLua(text), bytes: Buffer.byteLength(text) };
}

module.exports = { ROOT, OUTPUT, MODULES, build, write, checkLua, sha256 };

if (require.main === module) {
  try {
    const result = write();
    console.log(`built: ${path.relative(ROOT, result.output)} (${result.bytes} bytes)`);
    if (result.lua.checked && !result.lua.ok) {
      console.error(`Lua syntax check failed: ${result.lua.reason}`);
      process.exitCode = 1;
    } else if (!result.lua.checked) {
      console.log(`Lua syntax check skipped: ${result.lua.reason}`);
    } else {
      console.log('Lua 5.1 syntax OK');
    }
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
